from pathlib import Path
import re

p=Path('cafasso-wix-import/index.html')
s=p.read_text(encoding='utf-8')

css='''\n/* CAFASSO mobile app experience */\n.mobilebar{display:none}\n@media(max-width:680px){\n  body{padding-bottom:78px}\n  .shell{display:block;min-height:100vh}\n  .side{height:64px;position:sticky;top:0;z-index:40;padding:8px 14px;display:flex;align-items:center;justify-content:space-between;box-shadow:0 4px 18px rgba(15,45,77,.16)}\n  .side .brand{gap:9px}\n  .side .brand a{display:flex;align-items:center}\n  .side .brand img{width:36px;height:44px}\n  .side .brand div{display:block}\n  .side .brand b{font-size:22px}\n  .side .brand small{font-size:9px;margin-top:1px}\n  .side .nav,.side .foot{display:none!important}\n  main{padding:18px 14px 28px;max-width:none}\n  .top{display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}\n  .top h1{font-size:28px;line-height:1.08}\n  .top p{font-size:13px;margin-top:5px}\n  .pill{padding:5px;background:transparent;border:0}\n  .pill span{display:none}\n  .avatar{width:40px;height:40px}\n  .hero{border-radius:22px;padding:22px 18px;display:block}\n  .hero h2{font-size:30px;line-height:1.08;margin:8px 0 10px}\n  .hero p{font-size:14px;line-height:1.55}\n  .hero .quote{display:none}\n  .hero .btn{width:100%;padding:13px 15px}\n  .section{margin-top:22px}\n  .section h3{font-size:24px;margin-bottom:12px}\n  .courses{grid-template-columns:1fr;gap:12px}\n  .card{border-radius:18px;padding:17px}\n  .course h4{font-size:18px}\n  .course>div:last-child{gap:12px;align-items:center!important}\n  .course .btn{min-height:44px}\n  .stats{grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}\n  .stat{padding:14px;border-radius:14px}\n  .stat strong{font-size:24px}\n  .stat span{font-size:12px}\n  .module-detail{max-width:none}\n  .module{align-items:stretch;flex-direction:column;gap:12px}\n  .module-actions{justify-content:space-between;width:100%}\n  .module-actions .btn{flex:1;min-height:44px}\n  .block h4{font-size:19px}\n  .block-text{font-size:15px;line-height:1.65}\n  .activity textarea{min-height:150px;font-size:16px}\n  .activity-actions,.review-row,.complete-box{align-items:stretch;flex-direction:column}\n  .activity-actions .btn,.review-row .btn,.complete-box .btn{width:100%;min-height:46px}\n  .module-progress{border-radius:14px}\n  .backline{margin:2px 0 14px}\n  .backline button{padding:8px 0;font-size:14px}\n  .mobilebar{display:grid;grid-template-columns:repeat(4,1fr);position:fixed;left:0;right:0;bottom:0;z-index:60;background:#fff;border-top:1px solid var(--line);padding:6px 8px calc(6px + env(safe-area-inset-bottom));box-shadow:0 -8px 24px rgba(15,45,77,.09)}\n  .mobilebar button{appearance:none;border:0;background:transparent;color:var(--muted);font:inherit;font-size:10px;font-weight:800;padding:5px 2px;display:grid;place-items:center;gap:3px;cursor:pointer}\n  .mobilebar button::before{font-size:21px;line-height:1}\n  .mobilebar button[data-view="inicio"]::before{content:'⌂'}\n  .mobilebar button[data-view="cursos"]::before{content:'▤'}\n  .mobilebar button[data-view="certificados"]::before{content:'✓'}\n  .mobilebar button[data-view="perfil"]::before{content:'●'}\n  .mobilebar button.active{color:var(--navy)}\n  .mobilebar button.active::after{content:'';width:18px;height:3px;border-radius:999px;background:var(--gold)}\n}\n@media(max-width:380px){.top h1{font-size:25px}.hero h2{font-size:27px}.side .brand small{display:none}}\n'''
if '/* CAFASSO mobile app experience */' not in s:
    s=s.replace('</style>',css+'</style>',1)

if 'class="mobilebar"' not in s:
    mobile='<main id="main"></main><nav class="mobilebar" aria-label="Navegación principal"><button data-view="inicio">Inicio</button><button data-view="cursos">Cursos</button><button data-view="certificados">Logros</button><button data-view="perfil">Perfil</button></nav>'
    s,n=re.subn(r'<main\s+id=["\']main["\']\s*>\s*</main>',mobile,s,count=1)
    if n!=1:
        raise SystemExit('main element not found')

# Make the first brand crest a home link if it is not already wrapped.
if 'class="brand"><a href="./"' not in s:
    s,n=re.subn(r'(<div class=["\']brand["\']>)(<img[^>]+alt=["\']Maturana["\'][^>]*>)',r'\1<a href="./" aria-label="Volver al inicio" title="Volver al inicio">\2</a>',s,count=1)

p.write_text(s,encoding='utf-8')
print('Patched mobile animator experience')
